import { Scene } from 'phaser';

import { IMPERIAL_HEAT_REGISTRY_KEY, GAME_REGISTRY, type GameRegistry } from '../data/GameRegistry';
import {
    eventBus,
    EVENT_CLIENT_MURDERED,
    EVENT_HEAT_UPDATED,
    type ClientMurderedData,
    type HeatUpdatedData,
} from '../utils/EventBus';
/** Tracks Imperial attention generated by violent incidents in the cantina. */
export class ThreatManager {
    private heat: number;

    private readonly handleClientMurdered = (_data: ClientMurderedData): void => {
        this.heat += this.registry.threat.heatPerMurder;
        this.scene.registry.set(IMPERIAL_HEAT_REGISTRY_KEY, this.heat);
        const data: HeatUpdatedData = {
            currentHeat: this.heat,
            addedHeat: this.registry.threat.heatPerMurder,
        };
        eventBus.emit(EVENT_HEAT_UPDATED, data);
    };

    public constructor(
        private readonly scene: Scene,
        private readonly registry: GameRegistry = GAME_REGISTRY,
    ) {
        const storedHeat = this.scene.registry.get(IMPERIAL_HEAT_REGISTRY_KEY);
        this.heat = typeof storedHeat === 'number' ? storedHeat : this.registry.threat.startingHeat;
        this.scene.registry.set(IMPERIAL_HEAT_REGISTRY_KEY, this.heat);
        eventBus.on(EVENT_CLIENT_MURDERED, this.handleClientMurdered);
    }

    public destroy(): void {
        eventBus.off(EVENT_CLIENT_MURDERED, this.handleClientMurdered);
    }

    public get currentHeat(): number {
        return this.heat;
    }
}
